-- Mock _utils
_utils = {array = {new = function() return {} end}}
wf = {vars = {parsedCsv = {
    {SKU='A001', Discount='10%', Markdown=''},
    {SKU='A002', Discount='', Markdown='5%'},
    {SKU='A003', Discount=nil, Markdown=nil},
    {SKU='A004', Discount='', Markdown=''}
}}}
local result = {}
for _, item in ipairs(wf.vars.parsedCsv) do
    if (item.Discount ~= '' and item.Discount ~= nil) or (item.Markdown ~= '' and item.Markdown ~= nil) then table.insert(result, item) end
end
test_assert_eq(#result, 2, 'filtered to 2 items')
test_assert_eq(result[1].SKU, 'A001', 'first has discount')

_utils = {array = {new = function() return {} end}}
wf = {vars = {orders = {{status='completed'},{status='pending'},{status='completed'}}}}
